// Simple Orbital Escape game
// Canvas with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = canvas.clientWidth || 800;
  canvas.height = canvas.clientHeight || 600;

  // Ship definition
  const ship = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    angle: 0,
    radius: 10,
    vx: 0,
    vy: 0,
    thrust: 0.1,
    rotateSpeed: 0.07,
    update() {
      // Apply velocity
      this.x += this.vx;
      this.y += this.vy;
      // Screen wrap
      if (this.x < 0) this.x += canvas.width;
      if (this.x > canvas.width) this.x -= canvas.width;
      if (this.y < 0) this.y += canvas.height;
      if (this.y > canvas.height) this.y -= canvas.height;
    },
    draw() {
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate(this.angle);
      ctx.beginPath();
      ctx.moveTo(12, 0);
      ctx.lineTo(-8, -6);
      ctx.lineTo(-8, 6);
      ctx.closePath();
      ctx.fillStyle = 'white';
      ctx.fill();
      ctx.restore();
    },
  };

  // Asteroid definition
  const asteroids = [];
  const asteroidConfig = {
    minSize: 15,
    maxSize: 40,
    minSpeed: 0.5,
    maxSpeed: 2,
    spawnInterval: 2000, // ms
  };

  function spawnAsteroid() {
    const size = Math.random() * (asteroidConfig.maxSize - asteroidConfig.minSize) + asteroidConfig.minSize;
    // Spawn at random edge
    const edge = Math.floor(Math.random() * 4);
    let x, y, vx, vy;
    switch (edge) {
      case 0: // top
        x = Math.random() * canvas.width;
        y = -size;
        break;
      case 1: // right
        x = canvas.width + size;
        y = Math.random() * canvas.height;
        break;
      case 2: // bottom
        x = Math.random() * canvas.width;
        y = canvas.height + size;
        break;
      case 3: // left
        x = -size;
        y = Math.random() * canvas.height;
        break;
    }
    const speed = Math.random() * (asteroidConfig.maxSpeed - asteroidConfig.minSpeed) + asteroidConfig.minSpeed;
    const angle = Math.atan2(canvas.height / 2 - y, canvas.width / 2 - x) + (Math.random() - 0.5) * 0.5;
    vx = Math.cos(angle) * speed;
    vy = Math.sin(angle) * speed;
    asteroids.push({ x, y, vx, vy, r: size, angle: 0, rotSpeed: (Math.random() - 0.5) * 0.02 });
  }

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function handleInput() {
    if (keys['ArrowLeft'] || keys['a']) ship.angle -= ship.rotateSpeed;
    if (keys['ArrowRight'] || keys['d']) ship.angle += ship.rotateSpeed;
    if (keys['ArrowUp'] || keys['w']) {
      ship.vx += Math.cos(ship.angle) * ship.thrust;
      ship.vy += Math.sin(ship.angle) * ship.thrust;
    }
    if (keys['ArrowDown'] || keys['s']) {
      ship.vx *= 0.99;
      ship.vy *= 0.99;
    }
  }

  // Collision detection
  function checkCollisions() {
    for (const a of asteroids) {
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.r + ship.radius) return true;
    }
    return false;
  }

  let startTime = performance.now();
  let lastSpawn = performance.now();
  let gameOver = false;

  function update(dt) {
    if (gameOver) return;
    handleInput();
    ship.update();
    for (const a of asteroids) {
      a.x += a.vx;
      a.y += a.vy;
      a.angle += a.rotSpeed;
      // Wrap around edges
      if (a.x < -a.r) a.x += canvas.width + 2 * a.r;
      if (a.x > canvas.width + a.r) a.x -= canvas.width + 2 * a.r;
      if (a.y < -a.r) a.y += canvas.height + 2 * a.r;
      if (a.y > canvas.height + a.r) a.y -= canvas.height + 2 * a.r;
    }
    if (performance.now() - lastSpawn > asteroidConfig.spawnInterval) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }
    if (checkCollisions()) {
      gameOver = true;
    }
  }

  function draw() {
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // Draw ship
    ship.draw();
    // Draw asteroids
    ctx.strokeStyle = 'gray';
    ctx.lineWidth = 2;
    for (const a of asteroids) {
      ctx.save();
      ctx.translate(a.x, a.y);
      ctx.rotate(a.angle);
      ctx.beginPath();
      ctx.arc(0, 0, a.r, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
    // Score
    ctx.fillStyle = 'white';
    ctx.font = '16px sans-serif';
    const elapsed = ((performance.now() - startTime) / 1000).toFixed(1);
    ctx.fillText(`Time: ${elapsed}s`, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

  function loop(timestamp) {
    const dt = timestamp - (lastFrame ?? timestamp);
    lastFrame = timestamp;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  let lastFrame;
  requestAnimationFrame(loop);
})();
